const TG_COLECOES_PUBLICADAS=Object.keys(TG_PLANOS);
const TG_COLECOES_TODAS=['Power Up Start Smart','Power Up 1','Power Up 2','Power Up 3','Global Changer Starter','Global Changer 1','Global Changer 2','Global Changer 3','Own It 1','Own It 2','Own It 3','Own It 4','Shining Lights 5','Shining Lights 6','Shining Lights 7'];
const TG_COLECAO_MAP={
  kids:{'Pré-A1':'Power Up Start Smart','Pré A1':'Power Up Start Smart','Pre-A1':'Power Up Start Smart','Pré-A1+':'Power Up 1','Pré A1+':'Power Up 1','A1':'Power Up 2','A1+':'Power Up 3'},
  junior:{'A1':'Global Changer Starter','A1+':'Global Changer 1','A2':'Global Changer 2','A2+':'Global Changer 3'},
  teens:{'A1':'Own It 1','A2':'Own It 2','B1':'Own It 3','B1+':'Own It 4','B2':'Shining Lights 5','C1':'Shining Lights 6','C1+':'Shining Lights 7'}
};
const TG_COR={abertura:'#2E9E5B',nucleo:'#8f9aa6',buffer:'#E0A200',prova:'#D9603B',revisao:'#7E5BB5',ferias:'#b8b8b8'};
const TG_BG={abertura:'#E2EFDA',nucleo:'#ffffff',buffer:'#FFF2CC',prova:'#FCE4D6',revisao:'#F3F0FA',ferias:'#e6e6e6'};
const TG_TLABEL={abertura:'abertura',nucleo:'núcleo',buffer:'buffer',prova:'prova',revisao:'revisão',ferias:'férias'};

function _plLessons(col){ return (col&&TG_PLANOS[col])?TG_PLANOS[col]:null; }
function _plIdx(les,pos){ if(!les||!pos) return -1; for(let i=0;i<les.length;i++){ if(les[i].s===pos.s&&les[i].a===pos.a) return i; } return -1; }
function _lessonKey(l){ return l.s+'_'+l.a; }
function _umaVezSemana(t){ return !!(t && (t.vezesSemana===1 || ((t.dias||[]).length===1))); }
function _short(s,n){ s=String(s==null?'':s); return s.length>n?s.slice(0,n-1)+'…':s; }

/* ---- armazenamento em S.planejamento (lista: {id:turmaId, colecao, dadas, atualizadoEm}) ---- */
let _planMig=false;
function _planArr(){ if(!Array.isArray(S.planejamento)) S.planejamento=[]; if(!_planMig){ _planMig=true; _migraLegado(); } return S.planejamento; }
function _migraLegado(){
  try{
    const raw=localStorage.getItem('togethere_plan_v1'); if(!raw) return;
    const old=JSON.parse(raw)||{}; const arr=S.planejamento; let any=false;
    Object.keys(old).forEach(function(tid){ if(arr.some(x=>x.id===tid)) return; const o=old[tid]||{}; arr.push({id:tid,colecao:o.colecao||'',dadas:o.dadas,pos:o.pos,atualizadoEm:Date.now()}); any=true; });
    if(any && typeof save==='function') save();
  }catch(e){}
}
function _planRec(id){
  const arr=_planArr(); const rec=arr.find(x=>x.id===id); if(!rec) return null;
  if(!rec.dadas){                                   // normaliza registro antigo (pos → dadas)
    rec.dadas={};
    if(rec.pos && rec.colecao){ const les=_plLessons(rec.colecao); if(les){ const pi=_plIdx(les,rec.pos); for(let i=0;i<Math.max(0,pi);i++) rec.dadas[_lessonKey(les[i])]=1; } }
    delete rec.pos; delete rec.log; rec.atualizadoEm=Date.now(); if(typeof save==='function') save();
  }
  return rec;
}
function _planUpsert(id){ const arr=_planArr(); let rec=arr.find(x=>x.id===id); if(!rec){ rec={id:id,colecao:'',dadas:{}}; arr.push(rec); } return rec; }
function _planCommit(rec){ rec.atualizadoEm=Date.now(); if(typeof save==='function') save(); }
function planDaTurma(id){ return _planRec(id); }
function _dadasDe(id){ const p=_planRec(id); return (p&&p.dadas)?p.dadas:{}; }

function planColecaoSugerida(t){ if(!t) return null; const seg=(t.nivel||'').toLowerCase(); const m=TG_COLECAO_MAP[seg]; if(!m) return null; return m[(t.cefr||'').trim()]||null; }
function planColecaoDe(t){ if(!t) return null; const p=_planRec(t.id); if(p&&typeof p.colecao==='string'&&p.colecao) return p.colecao; return planColecaoSugerida(t); }

function _frontierIdx(les,dadas){ for(let i=0;i<les.length;i++){ if(!dadas[_lessonKey(les[i])]) return i; } return les.length; }
function _parseDMY(s){ const m=String(s||'').match(/(\d{1,2})\/(\d{1,2})/); if(!m) return null; return new Date(2026,(+m[2])-1,+m[1]); }
/* ---- data de início por turma (ancora a linha do tempo; guardada no registro do plano) ---- */
function _fmtISO(d){ const z=n=>String(n).padStart(2,'0'); return d.getFullYear()+'-'+z(d.getMonth()+1)+'-'+z(d.getDate()); }
function _parseISO(s){ const m=String(s||'').match(/(\d{4})-(\d{1,2})-(\d{1,2})/); if(!m) return null; return new Date(+m[1],(+m[2])-1,+m[3]); }
function _colInicio(les){ if(!les||!les.length) return new Date(2026,2,2); const a1=les.find(l=>l.a===1&&l.dt)||les.find(l=>l.dt); const d=a1?_parseDMY((a1.dt||'').split(' a ')[0]):null; return d||new Date(2026,2,2); }
function _planInicio(id){ const rec=_planRec(id); const t=S.turmas.find(x=>x.id===id); const les=_plLessons(planColecaoDe(t)); const iso=(rec&&rec.inicio)?_parseISO(rec.inicio):null; return iso||_colInicio(les); }
function _weekRangesShift(les,deltaDays){ const w={}; les.forEach(l=>{ if(l.a===1){ const p=(l.dt||'').split(' a '); const ini=_parseDMY(p[0]); const fim=_parseDMY(p[1]||p[0]); if(ini){ const i2=new Date(ini); i2.setDate(i2.getDate()+deltaDays); const f2=new Date(fim||ini); f2.setDate(f2.getDate()+deltaDays); w[l.s]={ini:i2,fim:f2}; } } }); return w; }
function _diasRecesso(de,ate){ let n=0; (S.recessos||[]).forEach(r=>{ const rd=_parseISO(r.de), ra=_parseISO(r.ate); if(!rd||!ra||ra<rd) return; const a=new Date(Math.max(+de,+rd)), b=new Date(Math.min(+ate,+ra)); const d=Math.floor((b-a)/86400000)+1; if(d>0) n+=d; }); return n; }
function semanaEsperada(id){
  const t=S.turmas.find(x=>x.id===id); const les=_plLessons(planColecaoDe(t)); if(!les) return semanaEscola();
  const base=_colInicio(les); const ini=_planInicio(id);
  const weeks=_weekRangesShift(les,0); const ns=Object.keys(weeks).map(Number).sort((a,b)=>a-b); if(!ns.length) return semanaEscola();
  const hoje=new Date(); hoje.setHours(0,0,0,0);
  let elapsed=Math.round((hoje-ini)/86400000); if(elapsed<=0) return ns[0];   // ainda não começou → 1ª semana
  elapsed-=_diasRecesso(ini,hoje); if(elapsed<0) elapsed=0;                    // dias de recesso/férias não avançam o ritmo
  const probe=new Date(base); probe.setDate(probe.getDate()+elapsed); probe.setHours(0,0,0,0);
  for(const w of ns){ const f=new Date(weeks[w].fim); f.setDate(f.getDate()+1); if(probe>=weeks[w].ini && probe<f) return w; }
  if(probe<weeks[ns[0]].ini) return ns[0];
  let last=ns[0]; for(const w of ns){ if(probe>=weeks[w].ini) last=w; } return last;
}
function definirInicioTurma(id){
  const el=document.getElementById('inicioSel'); const d=_parseISO(el?el.value:''); if(!d){ toast('Data inválida'); return; }
  const rec=_planUpsert(id); if(!rec.colecao){ const t=S.turmas.find(x=>x.id===id); rec.colecao=planColecaoDe(t)||''; }
  rec.inicio=_fmtISO(d); _planCommit(rec); toast('Início do ano atualizado');
  const _m=document.getElementById('modal'); if(_m){ _m.innerHTML=_timelineModalHTML(id); setTimeout(_scrollTlHere,50); }
}
/* ---- recessos / férias (calendário da escola; pausam o ritmo previsto) ---- */
function _fmtBR(iso){ const d=_parseISO(iso); if(!d) return iso||''; const z=n=>String(n).padStart(2,'0'); return z(d.getDate())+'/'+z(d.getMonth()+1)+'/'+d.getFullYear(); }
function abrirRecessos(){
  const rs=(S.recessos||[]).slice().sort((a,b)=>String(a.de).localeCompare(String(b.de)));
  const lista = rs.length ? rs.map(r=>'<div class="check"><span style="flex:1">'+(r.nome?('<b>'+esc(r.nome)+'</b> · '):'')+_fmtBR(r.de)+' → '+_fmtBR(r.ate)+'</span><button class="btn ghost sm" onclick="rmRecesso(\''+r.id+'\')">remover</button></div>').join('')
    : '<p class="hint">Nenhum recesso cadastrado ainda.</p>';
  modal('<h3>⚙️ Recessos e férias <button class="close" onclick="fechar()">×</button></h3>'+
    '<p class="hint" style="margin:-4px 0 10px">Nesses períodos o <b>ritmo previsto</b> (🎯) pausa — a turma não fica "atrasada" durante as férias. Use para as <b>férias de verão</b> (fim de um semestre e início do outro) e feriados prolongados. O recesso de julho já vem embutido no plano.</p>'+
    '<div style="margin-bottom:10px">'+lista+'</div>'+
    '<div style="border-top:.5px solid #e7eef6;padding-top:10px">'+
      '<label class="hint">Nome (opcional)</label><input id="recNome" placeholder="Ex.: Férias de verão 2026/27" style="margin:4px 0 8px">'+
      '<div style="display:flex;gap:8px;flex-wrap:wrap">'+
        '<div style="flex:1;min-width:130px"><label class="hint">Início do recesso</label><input type="date" id="recDe" style="width:100%"></div>'+
        '<div style="flex:1;min-width:130px"><label class="hint">Fim do recesso</label><input type="date" id="recAte" style="width:100%"></div>'+
      '</div>'+
      '<p class="hint" style="margin:6px 0 0">O <b>fim</b> é o último dia sem aula (a volta é no dia seguinte).</p>'+
      '<button class="btn block" style="margin-top:10px" onclick="addRecesso()">Adicionar recesso</button>'+
    '</div>');
}
function addRecesso(){
  const de=(document.getElementById('recDe')||{}).value, ate=(document.getElementById('recAte')||{}).value;
  const nome=((document.getElementById('recNome')||{}).value||'').trim();
  const d1=_parseISO(de), d2=_parseISO(ate);
  if(!d1||!d2){ toast('Preencha as duas datas'); return; }
  if(d2<d1){ toast('O fim não pode ser antes do início'); return; }
  S.recessos=S.recessos||[]; S.recessos.push({id:uid(),de:_fmtISO(d1),ate:_fmtISO(d2),nome:nome,atualizadoEm:Date.now()});
  if(typeof save==='function') save(); toast('Recesso adicionado'); abrirRecessos();
  if(typeof rota!=='undefined' && rota==='planejamento') renderPlanejamento();
}
function rmRecesso(id){
  S.recessos=(S.recessos||[]).filter(r=>r.id!==id);
  if(typeof marcarExcluido==='function') marcarExcluido('recessos',id);
  if(typeof save==='function') save(); toast('Recesso removido'); abrirRecessos();
  if(typeof rota!=='undefined' && rota==='planejamento') renderPlanejamento();
}
function semanaEscola(){
  const base=_plLessons('Own It 2')||_plLessons(TG_COLECOES_PUBLICADAS[0]); if(!base) return 1;
  const hoje=new Date(); hoje.setHours(0,0,0,0); const weeks={};
  base.forEach(l=>{ if(l.a===1){ const parts=(l.dt||'').split(' a '); const ini=_parseDMY(parts[0]); const fim=_parseDMY(parts[1]||parts[0]); if(ini) weeks[l.s]={ini,fim:fim||ini}; } });
  const ns=Object.keys(weeks).map(Number).sort((a,b)=>a-b); if(!ns.length) return 1;
  for(const w of ns){ const f=new Date(weeks[w].fim); f.setDate(f.getDate()+1); if(hoje>=weeks[w].ini && hoje<f) return w; }
  if(hoje<weeks[ns[0]].ini) return ns[0];
  let last=ns[0]; for(const w of ns){ if(hoje>=weeks[w].ini) last=w; } return last;
}

/* ---- ações ---- */
function planDefinirColecao(id,col){
  const rec=_planUpsert(id);
  if(col!==rec.colecao){ rec.dadas={}; delete rec.inicio; }
  rec.colecao=col||''; _planCommit(rec);
  if(typeof rota!=='undefined' && rota==='planejamento') renderPlanejamento();
}
function _toggleDada(id,key){
  const rec=_planUpsert(id); const t=S.turmas.find(x=>x.id===id);
  if(!rec.colecao) rec.colecao=planColecaoDe(t)||'';
  rec.dadas=rec.dadas||{}; if(rec.dadas[key]) delete rec.dadas[key]; else rec.dadas[key]=1;
  _planCommit(rec);
  const _sc=document.getElementById('tlScroll'); const _st=_sc?_sc.scrollTop:0;
  const _m=document.getElementById('modal'); if(_m){ _m.innerHTML=_timelineModalHTML(id); const _sc2=document.getElementById('tlScroll'); if(_sc2) _sc2.scrollTop=_st; }
}
function pedirPosicao(id){
  const t=S.turmas.find(x=>x.id===id); if(!t) return; const col=planColecaoDe(t); const les=_plLessons(col); if(!les) return;
  const unaVez=_umaVezSemana(t); let opts,ajuda;
  if(unaVez){
    const semanas=[]; les.forEach(l=>{ if(semanas.indexOf(l.s)<0) semanas.push(l.s); }); semanas.sort((a,b)=>a-b);
    opts=semanas.map(w=>{ const a1=les.find(l=>l.s===w&&l.a===1)||les.find(l=>l.s===w); const a2=les.find(l=>l.s===w&&l.a===2);
      const desc=((a1&&a1.u)?a1.u+' · ':'')+_short(((a1&&a1.sec)||'')+((a2&&a2.sec)?(' + '+a2.sec):''),34);
      return '<option value="'+w+'_1">Semana '+w+' — '+desc+'</option>'; }).join('');
    ajuda='Turma de <b>1x/semana</b> (as duas aulas no mesmo dia). Escolha a <b>próxima semana</b> a dar — tudo antes fica marcado como já dado.';
  } else {
    opts=les.map(l=>'<option value="'+l.s+'_'+l.a+'">Sem '+l.s+' · Aula '+l.a+' — '+l.u+' · '+_short(l.sec,32)+'</option>').join('');
    ajuda='Escolha a <b>próxima aula</b> a dar — tudo antes fica marcado como já dado.';
  }
  modal('<h3>📍 Onde vocês estão? <button class="close" onclick="fechar()">×</button></h3>'+
    '<p class="hint" style="margin:-4px 0 10px">Turma <b>'+t.nome+'</b> · '+col+'. '+ajuda+'</p>'+
    '<select id="posSel">'+opts+'</select>'+
    '<button class="btn block" style="margin-top:12px" onclick="salvarPosicao(\''+id+'\')">Confirmar</button>');
}
function salvarPosicao(id){
  const sel=document.getElementById('posSel'); if(!sel) return;
  const t=S.turmas.find(x=>x.id===id); const col=planColecaoDe(t); const les=_plLessons(col); if(!les){ fechar(); return; }
  const parts=sel.value.split('_'); const idx=_plIdx(les,{s:+parts[0],a:+parts[1]}); if(idx<0){ fechar(); return; }
  const rec=_planUpsert(id); rec.colecao=col; rec.dadas={};
  for(let i=0;i<idx;i++) rec.dadas[_lessonKey(les[i])]=1;
  _planCommit(rec); fechar(); modal(_timelineModalHTML(id)); setTimeout(_scrollTlHere,50);
}

/* ---- avanço automático ao marcar o plano feito ---- */
function _promptAvanco(turmaId){
  const rec=_planRec(turmaId); if(!rec) return;
  const t=S.turmas.find(x=>x.id===turmaId); const col=planColecaoDe(t); const les=_plLessons(col); if(!les) return;
  const dadas=_dadasDe(turmaId); const fi=_frontierIdx(les,dadas); if(fi>=les.length) return;
  const unaVez=_umaVezSemana(t); let idxs=[];
  if(unaVez){ const w=les[fi].s; les.forEach((l,i)=>{ if(l.s===w) idxs.push(i); }); }
  else { idxs=[fi]; if(fi+1<les.length) idxs.push(fi+1); }
  const pre = unaVez ? idxs.slice() : [fi];
  const rows=idxs.map(i=>{ const l=les[i]; const chk=pre.indexOf(i)>=0?'checked':'';
    return '<label style="display:flex;gap:9px;align-items:flex-start;padding:9px 10px;border:.5px solid #e7eef6;border-left:3px solid '+TG_COR[l.t]+';border-radius:8px;margin-bottom:6px;cursor:pointer"><input type="checkbox" data-i="'+i+'" '+chk+' style="margin-top:2px"><span><b>Sem '+l.s+' · Aula '+l.a+'</b> — '+esc(l.u)+(l.sec?(' · '+esc(l.sec)):'')+'</span></label>'; }).join('');
  modal('<h3>📅 Quanto avançou no planejamento? <button class="close" onclick="fechar()">×</button></h3>'+
    '<p class="hint" style="margin:-4px 0 10px">Só para controle interno — <b>não vai para o resumo dos pais</b>. Marque a(s) aula(s) do modelo que a turma deu hoje.</p>'+
    '<div id="avList">'+rows+'</div>'+
    '<div style="display:flex;gap:8px;margin-top:6px"><button class="btn block" onclick="_confirmarAvanco(\''+turmaId+'\')">Confirmar</button><button class="btn ghost" onclick="fechar()">Marcar depois</button></div>');
}
function _confirmarAvanco(turmaId){
  const t=S.turmas.find(x=>x.id===turmaId); const col=planColecaoDe(t); const les=_plLessons(col); if(!les){ fechar(); return; }
  const rec=_planUpsert(turmaId); if(!rec.colecao) rec.colecao=col; rec.dadas=rec.dadas||{};
  document.querySelectorAll('#avList input[type=checkbox]').forEach(function(cb){ const l=les[+cb.getAttribute('data-i')]; if(!l) return; const k=_lessonKey(l); if(cb.checked) rec.dadas[k]=1; else delete rec.dadas[k]; });
  _planCommit(rec); fechar(); toast('Avanço registrado');
}
if(typeof marcarPlanoFeito==='function'){
  const _pl_origMarcar=marcarPlanoFeito;
  marcarPlanoFeito=function(pid){
    _pl_origMarcar(pid);
    const p=S.planos.find(x=>x.id===pid); if(!p||!p.realizado) return;
    const t=S.turmas.find(x=>x.id===p.turmaId);
    if(t && _planRec(p.turmaId) && _plLessons(planColecaoDe(t))) setTimeout(function(){ abrirTimelineTurma(p.turmaId); },140);
  };
}

/* ---- telas ---- */
function renderPlanejamento(){
  const v=document.getElementById('view'); if(!v) return;
  let ts=(typeof turmasVisiveis==='function'?turmasVisiveis():(S.turmas||[]));
  if(typeof turmaStatus==='function') ts=ts.filter(t=>turmaStatus(t)!=='encerrada');
  const cards=ts.map(function(t){
    const col=planColecaoDe(t); const sug=planColecaoSugerida(t); const les=_plLessons(col); const pub=!!les;
    const rec=_planRec(t.id); const temPos=!!(rec&&rec.dadas&&Object.keys(rec.dadas).length);
    const opts=['<option value="">— escolher coleção —</option>'].concat(((typeof colecoesTodas==='function')?colecoesTodas():TG_COLECOES_TODAS).map(function(c){
      const has=TG_COLECOES_PUBLICADAS.indexOf(c)>=0; return '<option value="'+c+'" '+(c===col?'selected':'')+'>'+c+(has?'':' (em breve)')+'</option>'; })).join('');
    let corpo='';
    if(!col){ corpo='<p class="hint">Sem coleção definida.'+(sug?(' Sugestão pelo nível: <b>'+sug+'</b>.'):'')+'</p>'; }
    else if(!pub){ corpo='<p class="hint">O plano de <b>'+col+'</b> ainda não foi publicado no app.</p>'; }
    else {
      const fi=_frontierIdx(les,_dadasDe(t.id)); const at=(fi<les.length)?les[fi]:null;
      const posTxt=at?('Próxima aula: <b>Sem '+at.s+' · Aula '+at.a+'</b>'):'Plano concluído 🎉';
      corpo='<p class="hint" style="margin:2px 0 8px">'+posTxt+' · ritmo previsto: <b>Semana '+semanaEsperada(t.id)+'</b></p>'+
        '<button class="btn sm" onclick="abrirTimelineTurma(\''+t.id+'\')">📅 '+(temPos?'Abrir linha do tempo':'Definir posição e abrir')+'</button>';
    }
    return '<div class="card"><div class="section-title"><span class="feijao fj" style="background:var(--azul)"></span><h3 style="margin:0">'+t.nome+'</h3></div>'+
      '<p class="sub" style="margin:2px 0 8px">'+nivelTag(t.nivel)+(t.cefr?(' <span class="tag teens">'+t.cefr+'</span>'):'')+(_umaVezSemana(t)?' <span class="pill">1x/semana</span>':'')+'</p>'+
      '<label class="hint">Coleção do plano</label>'+
      '<select onchange="planDefinirColecao(\''+t.id+'\',this.value)" style="margin:4px 0 6px">'+opts+'</select>'+corpo+'</div>';
  }).join('');
  v.innerHTML='<div class="section-title"><span class="feijao fj" style="background:var(--amarelo)"></span><h2 class="display">Planejamento</h2></div>'+
    '<p class="sub">Controle interno do avanço de cada turma no plano-mestre. Cada turma tem sua própria <b>data de início</b> (defina na linha do tempo) — o ritmo previsto é calculado a partir dela, então turmas que começam em meses diferentes ficam certas. Marque as aulas dadas; ao marcar um plano como feito, o app já pergunta o avanço. Sincroniza entre aparelhos.</p>'+
    (S.perfil==='direcao'?'<button class="btn ghost sm" style="margin-bottom:10px" onclick="abrirRecessos()">⚙️ Recessos e férias</button>':'')+
    (cards||'<p class="hint">Nenhuma turma visível.</p>');
  window.scrollTo(0,0);
}
VIEWS.planejamento=renderPlanejamento;
