            <button type="button" onclick="toggleSenhaLogin(this,'waSenhaDir')" aria-label="Mostrar senha" title="Mostrar senha" style="position:absolute;right:6px;top:50%;transform:translateY(-50%);background:none;border:none;font-size:1.15rem;cursor:pointer;padding:6px;line-height:1">👁️</button>
